+            }
+  - do:
+      security.put_role:
+        name: "remote_ccs"
+        body:  >
+            {
+            }
+---
+teardown:
+  - do:
+      security.delete_user:
+        username: "joe"
+        ignore: 404
+  - do:
+      security.delete_role:
+        name: "x_cluster_role"
+        ignore: 404
+
+---
