+               "data": { "type": "long" },
+               "color": { "type": "keyword" }
+             }
+            """;
+        RestClient localClient = client();
+        localDocs = IntStream.range(0, between(1, 500))
+            .mapToObj(n -> new Doc(n, randomFrom("red", "yellow", "green"), randomIntBetween(1, 1000)))
+            .toList();
+        createIndex(
+            localClient,
+            localIndex,
